import React, { useState, useEffect } from "react";
import { Routes, Route } from "react-router-dom"; 
import NavBar from "./components/NavBar/NavBar";
import Upload from "./components/Upload/Upload";
import Feedback from "./components/FeedBack/Feedback";
import Library from "./components/Library/Library";
import Main from "./components/mainpage/main"; 
import AboutUs from "./components/Aboutus/Aboutus";
import Signup from "./components/Signup/Signup";
import Login from "./components/Login/Login";
import LoginModal from "./components/LoginModal/LoginModal"; // import your popup modal
import "./App.css";

function App() {
    const [currentUser, setCurrentUser] = useState(() => {
        const savedUser = localStorage.getItem("currentUser");
        return savedUser ? JSON.parse(savedUser) : null;
    });

    const [isLoginModalOpen, setLoginModalOpen] = useState(false);

    useEffect(() => {
        if (currentUser) {
            localStorage.setItem("currentUser", JSON.stringify(currentUser));
        } else {
            localStorage.removeItem("currentUser");
        }
    }, [currentUser]);

    const requireAuth = (Component) => {
        return currentUser ? (
            <Component />
        ) : (
            <>
              {setLoginModalOpen(true)}
              <Main /> {/* fallback page instead of Navigate */}
            </>
        );
    };

    return (
        <div className="app-container">
            <NavBar 
                user={currentUser} 
                setCurrentUser={setCurrentUser}
                openLoginModal={() => setLoginModalOpen(true)}
            />

            <div className="main-content">
                <Routes>
                    <Route path="/" element={<Main />} />
                    <Route path="/aboutus" element={<AboutUs />} />
                    <Route path="/signup" element={<Signup setCurrentUser={setCurrentUser} />} />
                    <Route path="/login" element={<Login setCurrentUser={setCurrentUser} />} />

                    <Route path="/dashboard" element={requireAuth(Upload)} />
                    <Route path="/feedback" element={requireAuth(Feedback)} />
                    <Route path="/library" element={requireAuth(Library)} />
                </Routes>
            </div>

            <LoginModal 
                isOpen={isLoginModalOpen} 
                onClose={() => setLoginModalOpen(false)}
                setCurrentUser={setCurrentUser}
            />
        </div>
    );
}

export default App;
